		return err
	}
	apiURL := getenv("MIRROR_API_URL")
	if apiURL == "" {
		apiURL = defaultAPIURL
	}
	client := NewClient(apiURL, env["MIRROR_API_KEY"])

	if _, err := client.Account(ctx); err != nil {
